@layer components {
  .feed-page {
    background-color: var(--shelf-bgColor-page);
    color: var(--shelf-fgColor-default);
    min-block-size: 100vh;
    padding-block: var(--shelf-space-lg);
    padding-inline: var(--shelf-space-md);
  }

  .feed-page-wrapper {
    max-inline-size: 960px;
    margin-inline: auto;
  }

  .feed-page-heading {
    color: var(--shelf-fgColor-heading);
    font-size: var(--shelf-fontSize-xl);
    font-weight: var(--shelf-fontWeight-bold);
    margin-block-end: var(--shelf-space-lg);
  }

  .feed-list {
    list-style: none;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-md);
  }

  .feed-item {
    background-color: var(--shelf-bgColor-card);
    border: 1px solid var(--shelf-borderColor-default);
    border-radius: var(--shelf-borderRadius-md);
    padding: var(--shelf-space-md);
  }

  .feed-item-title {
    color: var(--shelf-fgColor-default);
    font-size: var(--shelf-fontSize-md);
    font-weight: var(--shelf-fontWeight-semibold);
    margin-block-end: var(--shelf-space-sm);
  }

  .feed-item-description {
    color: var(--shelf-fgColor-muted);
    font-size: var(--shelf-fontSize-sm);
  }
}
